class Solution {
public:
    std::vector<int> arrayChange(std::vector<int>& nums, std::vector<std::vector<int>>& operations) {
        std::unordered_map<int, int> pos;
        for (int i = 0; i < (int)nums.size(); ++i) pos[nums[i]] = i;
        for (const auto& op : operations) {
            int old_val = op[0], new_val = op[1];
            int idx = pos[old_val];
            nums[idx] = new_val;
            pos.erase(old_val);
            pos[new_val] = idx;
        }
        return nums;
    }
};

class Solution {
    public int[] arrayChange(int[] nums, int[][] operations) {
        java.util.Map<Integer, Integer> pos = new java.util.HashMap<>();
        for (int i = 0; i < nums.length; i++) pos.put(nums[i], i);
        for (int[] op : operations) {
            int oldVal = op[0], newVal = op[1];
            int idx = pos.remove(oldVal);
            nums[idx] = newVal;
            pos.put(newVal, idx);
        }
        return nums;
    }
}

var arrayChange = function(nums, operations) {
    const pos = new Map();
    for (let i = 0; i < nums.length; i++) pos.set(nums[i], i);
    for (const [oldVal, newVal] of operations) {
        const idx = pos.get(oldVal);
        nums[idx] = newVal;
        pos.delete(oldVal);
        pos.set(newVal, idx);
    }
    return nums;
};
